from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """##### 出目46 <車両IED>\n\n- 属性：屋外\n_停車していた車両が突然爆発する。爆風と炎上する残骸が通りを塞ぐ。_\n\n分隊は二手に分断される。\n  被弾ロールを1回行い、出目の役割の隊員は次の戦闘の第1ラウンドに参加できない。(被弾ロールの対象にもならない。)\n  さらに、次に発生する戦闘では、各ラウンドに攻撃へ参加できる分隊員数の上限を、その戦闘開始時の生存戦闘員数 -2（最低1）とする。分隊長はこの上限に含めない。\n"""
new = """##### 出目46 <車両IED>\n\n- 属性：屋外\n_停車していた車両が突然爆発する。爆風と炎上する残骸が通りを塞ぐ。_\n\n分隊は二手に分断される。\n  【被弾ロール】を1回行い、対象となった分隊員は次の戦闘の第1ラウンドに参加できない（【被弾ロール】の対象にもならない）。【被弾ロール】の対象となれる戦闘員が1名もおらず、Core v1.01の共通フォールバックによって分隊長が対象となった場合、分隊長は次の戦闘の第1ラウンドに自分の行動を行えない。ただし分隊長は戦場には存在するため、敵の攻撃対象にはなり、通常どおり防御ロールを行う。第2ラウンドから通常どおり行動できる。\n  さらに、次に発生する戦闘では、各ラウンドに攻撃へ参加できる分隊員数の上限を、その戦闘開始時の生存戦闘員数 -2（最低1）とする。分隊長はこの上限に含めない。\n"""
if s.count(old) != 1:
    raise SystemExit(f"event46 marker count must be 1, got {s.count(old)}")
scenario.write_text(s.replace(old, new, 1), encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 29. Black Sun 出目46の分隊長フォールバック — 採用済み"
section = """

## 29. Black Sun 出目46の分隊長フォールバック — 採用済み

ユーザー承認により、出目46【車両IED】でCore v1.01の【被弾ロール】共通フォールバックにより分隊長が対象となった場合の処理を明確化する。

- 通常は【被弾ロール】で対象となった分隊員が、次の戦闘の第1ラウンドに参加できず、【被弾ロール】の対象にもならない。
- 対象となれる戦闘員が1名もいない場合は、Core v1.01の共通規定により分隊長を対象とする。
- 分隊長が対象となった場合、次の戦闘の第1ラウンドは自分の行動を行えない。
- ただし分隊長は戦場から除外されず、敵の攻撃対象にはなる。敵の攻撃を受ける場合は通常どおり防御ロールを行う。
- 第2ラウンドから分隊長は通常どおり行動できる。
- 既存の「各ラウンドに攻撃へ参加できる分隊員数＝戦闘開始時の生存戦闘員数 -2（最低1）、分隊長は上限外」という制限は変更しない。

これにより、戦闘員0名の編成でも敵の攻撃対象が消失せず、車両IEDによる第1ラウンドの行動阻害を維持できる。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
